import { API_BASE_URL } from '../utils/api';

export const loginSalesStaff = async (credentials) => {
  try {
    // 首先獲取銷售人員列表來驗證用戶
    const salesStaffResponse = await fetch(`${API_BASE_URL}/api/sales-staffs?populate=*`);
    
    if (!salesStaffResponse.ok) {
      throw new Error(`獲取數據失敗: ${salesStaffResponse.status}`);
    }
    
    const salesData = await salesStaffResponse.json();
    console.log('獲取到的銷售人員數據:', salesData);
    
    // 找到匹配的用戶
    const salesUser = salesData.data.find(staff => 
      staff.attributes.username === credentials.username && 
      staff.attributes.password === credentials.password
    );
    
    if (!salesUser) {
      throw new Error('用戶名或密碼錯誤');
    }
    
    console.log('銷售人員驗證成功:', {
      id: salesUser.id,
      username: salesUser.attributes.username,
      role: salesUser.attributes.role
    });
    
    // 嘗試使用 Strapi 的認證 API 獲取 JWT token
    // 但是由於我們使用的是自定義的 sales-staff 內容類型，不是 users
    // 我們需要創建一個臨時的認證解決方案
    
    // 暫時使用 admin 認證來獲取 JWT
    // 注意：這是一個臨時解決方案，生產環境中需要正確配置權限
    try {
      const authResponse = await fetch(`${API_BASE_URL}/api/auth/local`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          identifier: 'admin@example.com', // 需要設置一個通用的管理員帳戶
          password: 'admin123' // 或者從環境變量獲取
        }),
      });
      
      if (authResponse.ok) {
        const authData = await authResponse.json();
        
        // 創建包含完整資訊的用戶對象
        const userWithJwt = {
          id: salesUser.id,
          username: salesUser.attributes.username,
          name: salesUser.attributes.name,
          role: salesUser.attributes.role,
          jwt: authData.jwt
        };
        
        console.log('登入成功，用戶資訊:', userWithJwt);
        
        // 儲存到 localStorage
        localStorage.setItem('token', authData.jwt);
        localStorage.setItem('user', JSON.stringify(userWithJwt));
        localStorage.setItem('salesStaff', JSON.stringify(userWithJwt));
        
        return {
          jwt: authData.jwt,
          user: userWithJwt
        };
      }
    } catch (authError) {
      console.warn('無法獲取 Strapi JWT，使用臨時方案:', authError);
    }
    
    // 如果無法獲取真實 JWT，暫時禁用認證檢查
    // 這需要在 Strapi 中配置 API 為公開訪問
    const tempToken = `temp_${Date.now()}`;
    
    const userWithTempToken = {
      id: salesUser.id,
      username: salesUser.attributes.username,
      name: salesUser.attributes.name,
      role: salesUser.attributes.role,
      jwt: tempToken
    };
    
    console.log('使用臨時認證方案:', userWithTempToken);
    
    localStorage.setItem('token', tempToken);
    localStorage.setItem('user', JSON.stringify(userWithTempToken));
    localStorage.setItem('salesStaff', JSON.stringify(userWithTempToken));
    
    return {
      jwt: tempToken,
      user: userWithTempToken
    };
    
  } catch (error) {
    console.error('登入錯誤:', error);
    throw error;
  }
};

export const checkAuth = () => {
  const token = localStorage.getItem('token');
  const user = JSON.parse(localStorage.getItem('user') || 'null');
  
  return {
    isAuthenticated: !!token && !!user,
    user,
    token
  };
};

export const logout = () => {
  localStorage.removeItem('token');
  localStorage.removeItem('user');
  localStorage.removeItem('salesStaff');
  window.location.href = '/#/crm/login';
}; 