import React, { useState, useEffect } from 'react';
import { Row, Col, Card, Statistic, Table, DatePicker } from 'antd';
import {
  UserOutlined,
  TeamOutlined,
  FormOutlined,
  RiseOutlined,
} from '@ant-design/icons';
import styles from './SalesOverview.module.css';

const { RangePicker } = DatePicker;

const SalesOverview = () => {
  const [statistics, setStatistics] = useState({
    totalCustomers: 0,
    activeCustomers: 0,
    totalRegistrations: 0,
    conversionRate: 0,
  });

  const [recentInteractions, setRecentInteractions] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // 模擬加載數據
    setTimeout(() => {
      setStatistics({
        totalCustomers: 156,
        activeCustomers: 89,
        totalRegistrations: 45,
        conversionRate: 28.8,
      });
      
      setRecentInteractions([
        {
          key: '1',
          customerName: '王小明',
          type: '電話聯繫',
          date: '2024-03-15',
          status: '有興趣',
          notes: '對A案場表示興趣，預約下週看屋',
        },
        // ... 更多互動記錄
      ]);
      
      setLoading(false);
    }, 1000);
  }, []);

  const columns = [
    {
      title: '客戶姓名',
      dataIndex: 'customerName',
      key: 'customerName',
    },
    {
      title: '互動類型',
      dataIndex: 'type',
      key: 'type',
    },
    {
      title: '日期',
      dataIndex: 'date',
      key: 'date',
    },
    {
      title: '狀態',
      dataIndex: 'status',
      key: 'status',
      render: (status) => (
        <span className={styles.statusTag}>{status}</span>
      ),
    },
    {
      title: '備註',
      dataIndex: 'notes',
      key: 'notes',
      ellipsis: true,
    },
  ];

  return (
    <div className={styles.overview}>
      <div className={styles.header}>
        <h2>銷售總覽</h2>
        <RangePicker className={styles.datePicker} />
      </div>

      <Row gutter={[24, 24]}>
        <Col xs={24} sm={12} lg={6}>
          <Card className={styles.statCard}>
            <Statistic
              title="總客戶數"
              value={statistics.totalCustomers}
              prefix={<TeamOutlined />}
              loading={loading}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card className={styles.statCard}>
            <Statistic
              title="活躍客戶"
              value={statistics.activeCustomers}
              prefix={<UserOutlined />}
              loading={loading}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card className={styles.statCard}>
            <Statistic
              title="報名總數"
              value={statistics.totalRegistrations}
              prefix={<FormOutlined />}
              loading={loading}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card className={styles.statCard}>
            <Statistic
              title="轉換率"
              value={statistics.conversionRate}
              precision={1}
              suffix="%"
              prefix={<RiseOutlined />}
              loading={loading}
            />
          </Card>
        </Col>
      </Row>

      <Card
        title="最近互動記錄"
        className={styles.tableCard}
        bodyStyle={{ padding: 0 }}
      >
        <Table
          columns={columns}
          dataSource={recentInteractions}
          loading={loading}
          pagination={{ pageSize: 5 }}
        />
      </Card>
    </div>
  );
};

export default SalesOverview; 