// API 基本配置
export const API_BASE_URL = 'https://eloquent-splendor-a265f51ba3.strapiapp.com';

// 獲取認證頭
const getAuthHeaders = () => {
  const token = localStorage.getItem('token');
  return {
    'Content-Type': 'application/json',
    ...(token && { 'Authorization': `Bearer ${token}` })
  };
};

// 統一的 API 請求函數
export const apiRequest = async (url, options = {}) => {
  const { headers = {}, ...restOptions } = options;
  
  const config = {
    headers: {
      ...getAuthHeaders(),
      ...headers
    },
    ...restOptions
  };

  console.log('API 請求配置:', config);
  console.log('完整 URL:', `${API_BASE_URL}${url}`);

  const response = await fetch(`${API_BASE_URL}${url}`, config);
  
  console.log('API 響應狀態:', response.status);
  
  if (!response.ok) {
    if (response.status === 401) {
      // 認證失敗，清除本地存儲並重定向到登入頁
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      localStorage.removeItem('salesStaff');
      window.location.href = '/#/crm/login';
      throw new Error('認證已過期，請重新登入');
    }
    throw new Error(`API請求失敗: ${response.status}`);
  }

  return response.json();
};

// GET 請求
export const apiGet = (url) => apiRequest(url);

// POST 請求
export const apiPost = (url, data) => apiRequest(url, {
  method: 'POST',
  body: JSON.stringify(data)
});

// PUT 請求
export const apiPut = (url, data) => apiRequest(url, {
  method: 'PUT',
  body: JSON.stringify(data)
});

// DELETE 請求
export const apiDelete = (url) => apiRequest(url, {
  method: 'DELETE'
}); 